using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class AllPavingRestore{static AllPavingRestore(){EditorApplication.delayCall+=Run;}static void Run(){if(!File.Exists("AllPavingRestore.request"))return;File.Delete("AllPavingRestore.request");try{var sc=SceneManager.GetActiveScene();var maps=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CityGroundTextureLayout>(true)).ToArray();foreach(var m in maps)m.Apply();var plots=maps.SelectMany(m=>m.plots).Where(p=>p.renderer).ToArray();if(plots.Any(p=>ShaderUtil.ShaderHasError(p.renderer.sharedMaterial.shader)))throw new Exception("Ground shader errors");var log=plots.Select(p=>p.renderer.name+" kind="+p.data.x+" patches="+p.data.z+" offset="+(new Vector2(p.renderer.bounds.center.x,p.renderer.bounds.center.z)-new Vector2(p.rect.x,p.rect.y))).ToArray();var ctrl=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CityDayNightController>(true)).First();bool night=ctrl.IsNight;try{ctrl.Apply(false);foreach(var p in plots.GroupBy(p=>p.data.x).Select(g=>g.First())){var c=p.renderer.bounds.center;float h=Mathf.Clamp(Mathf.Max(p.rect.z,p.rect.w)*1.8f,65,200);CityLightingBuilder.Capture(ctrl,Tuple.Create(c+new Vector3(0,h,8),Quaternion.LookRotation(new Vector3(0,-h,-8))),"Paving-Restored-Type-"+p.data.x);}}finally{ctrl.Apply(night);}EditorSceneManager.MarkSceneDirty(sc);EditorSceneManager.SaveScene(sc);File.WriteAllText("FinalEnvironmentRoadReview/AllPavingRestore.txt","SUCCESS all "+plots.Length+" existing paving plots reapplied. Shader errors=0. Existing layouts and assets retained, coordinates follow current renderer placement. No new materials/textures/meshes/lights.\n"+string.Join("\n",log));}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/AllPavingRestore.txt",e.ToString());}}}
